// AgentStep A step in an agent's execution flow that defines how the agent processes and responds to input.
// The step name comes from the map key in the agent's steps map.
//
// A step receives all previous session history, including any prior agent steps.
// The agent then follows the step's instructions to decide what to do.
// Finally, the agent stops if no next step is defined, or continues to the first
// next step whose condition matches.
//
// An agent always executes steps serially. For parallel behavior, give the agent
// other agents as tools.
//
// Each step can only use tools defined by its `allowed_tools` list. If this list is not
// specified, all tools known to the agent are allowed.
type AgentStep struct {
	// AllowedSkills List of skill names that this step is allowed to use.
	// If not specified (null), all skills defined in the agent's skills map are allowed.
	// If set to an empty array, no skills are available and the invoke_skill tool is not shown.
	//
	//
	// Example: ["code_review","debugging"]
	AllowedSkills *[]string `json:"allowed_skills,omitempty"`

	// AllowedTools List of tool configuration names that this step is allowed to use.
	// If not specified (null), all tools defined in the agent's tool_configurations are allowed.
	// If set to an empty array, no tools are allowed and the agent can only respond with text.
	// Tool names must reference keys in the agent's tool_configurations map.
	//
	//
	// Example: ["customer_search","web_search"]
	AllowedTools *[]string `json:"allowed_tools,omitempty"`

	// Instructions List of instructions that guide the agent's behavior in this step.
	// If omitted, the agent has no system instructions. It then simply responds to the user
	// input and previous session history, which may produce odd behavior.
	Instructions []AgentStepInstruction `json:"instructions"`

	// NextSteps Conditional transitions to other steps.
	// Evaluated in order; first matching condition is selected.
	// A next_step without a condition acts as a catch-all/default.
	// If no condition matches, the agent remains on the current step and the agent ends output.
	NextSteps *[]NextStep `json:"next_steps,omitempty"`

	// OutputParser How to parse and format the agent's output.
	// Determines which event type is emitted.
	// Defaults to 'default' parser if not specified.
	OutputParser AgentOutputParser `json:"output_parser"`

	// ReentryStep Step name to resume at when the session receives the next user message.
	// If not specified, the session re-enters at this step (i.e., stays here).
	// Set to the agent's first_step_name to always restart from the beginning.
	//
	//
	// Example: classifier
	ReentryStep *string `json:"reentry_step,omitempty"`

	// Reminders Reminders injected into conversation messages when specific events occur. Useful for keeping the agent on-task during long conversations.
	Reminders *[]AgentStepReminder `json:"reminders,omitempty"`

	// Type Deprecated. This field is ignored and exists only for backward compatibility.
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	Type *string `json:"type,omitempty"`
}

