// BaseScimSourceConfiguration Base SCIM source configuration. Ingests user records from a SCIM 2.0 service provider
// through the Users endpoint. Each user becomes one document carrying profile, group
// membership, and enterprise attributes as document metadata for attribute-based filtering.
type BaseScimSourceConfiguration struct {
	// Attributes Attribute names to request from the service provider, passed as the SCIM attributes
	// query parameter. The meta attribute is always requested so that incremental sync can
	// read each user's meta.lastModified timestamp. When unset, the service provider
	// returns its default attribute set. Returned attributes land in two places on each
	// record. They are rendered into the user's profile document, which the agent converts
	// and indexes. They also populate the record's source_record_metadata in the agent
	// session metadata, where they are available for attribute-based filtering and for
	// tool argument overrides. Narrowing this list therefore narrows both what is indexed
	// and what is available as metadata. An attribute the service provider marks as
	// returned only on request is included only when named here.
	//
	//
	// Example: ["userName","name","emails","groups","active"]
	Attributes *[]string `json:"attributes,omitempty"`

	// Auth Authentication configuration for connecting to a remote service.
	Auth *RemoteAuth `json:"auth,omitempty"`

	// BaseUrl Base URL of the SCIM 2.0 service provider. The Users resource path is appended
	// automatically and must not be included.
	//
	//
	// Example: https://example.okta.com/scim/v2
	BaseUrl *string `json:"base_url,omitempty"`

	// Filter SCIM filter expression applied to the user listing, restricting which users are
	// ingested. Requires a service provider that supports the filter query parameter.
	// When `incremental_strategy` is `last_modified_filter`, the change window is combined
	// with this expression.
	//
	//
	// Example: userType eq "Employee"
	Filter *string `json:"filter,omitempty"`

	// IncrementalStrategy How incremental syncs detect changed users. `last_modified_filter` pushes the change
	// window into the SCIM filter query parameter as a `meta.lastModified` range.
	// `client_side` enumerates every user on each run and evaluates the change window
	// locally. Support for the filter query parameter is optional in the SCIM 2.0
	// specification. Set `client_side` when the service provider does not support
	// filtering on `meta.lastModified`.
	IncrementalStrategy *BaseScimSourceConfigurationIncrementalStrategy `json:"incremental_strategy,omitempty"`

	// Type Example: scim
	Type string `json:"type"`
}

// BaseScimSourceConfigurationIncrementalStrategy How incremental syncs detect changed users. `last_modified_filter` pushes the change
// window into the SCIM filter query parameter as a `meta.lastModified` range.
// `client_side` enumerates every user on each run and evaluates the change window
// locally. Support for the filter query parameter is optional in the SCIM 2.0
// specification. Set `client_side` when the service provider does not support
// filtering on `meta.lastModified`.
type BaseScimSourceConfigurationIncrementalStrategy string

