// ConnectorConfiguration Read view of a connector's configuration, as returned by GET and list
// endpoints. Contains the secrets supplied at create time alongside
// platform-derived display fields:
// - Slack exposes `webhook_path`
// - gchat exposes `audience_url` and `client_email`
// - zoom exposes the generated `connector_token` and `webhook_path`
type ConnectorConfiguration struct {
	union json.RawMessage
}

// ConnectorConfigurationBase Properties shared by every connector configuration read view.
type ConnectorConfigurationBase struct {
	// HiddenOutputTypes Agent output types omitted from the connector's channel; the final response is always posted.
	//
	// Example: ["tool_calls"]
	HiddenOutputTypes *[]AgentOutputType `json:"hidden_output_types,omitempty"`
}

// ConnectorId The globally unique identifier of a connector.
//
// Example: con_support_9f3a1c2b4d5e6f708192a3b4c5d6e7f8
type ConnectorId = string

// ConnectorStatus The current status of the connector.
//
// Example: active
type ConnectorStatus string

// ConnectorWebhookStatus Outcome of the most recently received inbound webhook. Absent until the
// first webhook arrives. Values:
// - `success`: the webhook verified and the event was accepted.
// - `jwt_verification_failed`: the bearer token was missing or could not be verified.
// - `audience_mismatch`: the token was valid but its aud did not equal the connector's audience_url.
// - `auth_failed`: the inbound request lacked or did not match the connector's authentication secret.
// - `missing_signature`: the request lacked the signature needed for an asynchronous reply.
// - `missing_engagement`: the request lacked the engagement identifier needed to route the session.
// - `event_parse_failed`: the event body could not be parsed.
// - `internal_error`: an unexpected error occurred after the connector was resolved.
// - `unknown`: the outcome could not be classified.
//
// Example: success
type ConnectorWebhookStatus string

// ContextConfiguration Configuration for the presentation of each document part in the result set. Use either `characters_before`/`characters_after` or `sentences_before`/`sentences_after`; if both are set, `sentences_*` takes precedence. Setting `full_document_context: true` overrides both and returns the entire matching document as context.
//
// Example: {"end_tag":"\u003c/em\u003e","sentences_after":2,"sentences_before":2,"start_tag":"\u003cem\u003e"}
type ContextConfiguration struct {
	// CharactersAfter The number of characters to show after the matching document part. This shows the context of the part in the wider document. Ignored if `sentences_after` is set. The platform captures the full sentence that contains the captured characters, so a truncated word or sentence does not lose meaning.
	CharactersAfter *int32 `json:"characters_after,omitempty"`

	// CharactersBefore The number of characters to show before the matching document part. This shows the context of the part in the wider document. Ignored if `sentences_before` is set. The platform captures the full sentence that contains the captured characters, so a truncated word or sentence does not lose meaning.
	CharactersBefore *int32 `json:"characters_before,omitempty"`

	// EndTag The tag that wraps the end of the document part. Use an HTML/XML tag or another delimiter. Your application can use the tag to highlight the part in your UI. The tag also marks where the document part ends and the following context begins.
	//
	// Example: </em>
	EndTag *string `json:"end_tag,omitempty"`

	// FullDocumentContext When true, the platform returns the entire document that contains the matching part as context. `characters_before`/`characters_after` and `sentences_before`/`sentences_after` are ignored.
	FullDocumentContext *bool `json:"full_document_context,omitempty"`

	// SentencesAfter The number of sentences to show after the matching document part. This shows the context of the part in the wider document.
	//
	// Example: 2
	SentencesAfter *int32 `json:"sentences_after,omitempty"`

	// SentencesBefore The number of sentences to show before the matching document part. This shows the context of the part in the wider document.
	//
	// Example: 2
	SentencesBefore *int32 `json:"sentences_before,omitempty"`

	// StartTag The tag that wraps the start of the document part. Use an HTML/XML tag or another delimiter. Your application can use the tag to highlight the part in your UI. The tag also marks where the preceding context ends and the document part begins.
	//
	// Example: <em>
	StartTag *string `json:"start_tag,omitempty"`
}

// ContextConsumedEvent Token usage event reporting context window consumption.
type ContextConsumedEvent struct {
	// CreatedAt Timestamp when the event was created.
	//
	// Example: 2024-01-15T10:35:00Z
	CreatedAt time.Time `json:"created_at"`

	// SessionContextUsage Token usage of the session's most recent agent call, reflecting current context window consumption. Not a running total across calls.
	SessionContextUsage SessionContextUsage `json:"session_context_usage"`

	// Type The event type.
	//
	// Example: context_consumed
	Type string `json:"type"`
}

// ContextLimitExceededEvent A turn-ending event indicating the current request exceeded the agent's context limit.
// A subsequent turn can succeed once the context is reduced, for example by compacting the session
// or sending a shorter input. Persisted to the session history.
type ContextLimitExceededEvent struct {
	// ActualTokens The actual number of tokens in the request
	//
	// Example: 140658
	ActualTokens *int64 `json:"actual_tokens,omitempty"`

	// ContextLimit The maximum number of tokens allowed by the model
	//
	// Example: 128000
	ContextLimit *int64 `json:"context_limit,omitempty"`

	// CreatedAt Timestamp when the event was created.
	//
	// Example: 2024-01-15T10:35:00Z
	CreatedAt time.Time `json:"created_at"`

	// Id The unique identifier for the event.
	//
	// Example: aev_user_001
	Id string `json:"id"`

	// Message Human-readable error message
	//
	// Example: Context limit exceeded: 140658 tokens used, 128000 limit
	Message string `json:"message"`

	// SessionKey A unique key that identifies an agent session.
	//
	// Example: customer_support_chat
	SessionKey AgentSessionKey `json:"session_key"`

	// Type The type of event.
	Type string `json:"type"`
}

// CoreDocument A document composed of explicitly specified document parts. Each part maps directly to a search result.
//
// Example: {"document_parts":[{"metadata":{"quarter":1,"year":2023},"text":"This invoice includes customer billing history for Q1."}],"extraction_usage":{"table_extraction_used":1},"id":"invoice-001","images":[{"caption":"Sales growth trends for Q1 to Q4 of 2024","description":"A bar chart showing quarterly sales growth, with Q4 outperforming all previous quarters by 15%","id":"image_1","image_data":{"data":"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGP4//8/AAX+Av4N70a4AAAAAElFTkSuQmCC","mime_type":"image/jpeg"},"title":"Quarterly Sales Performance"}],"metadata":{"doc_type":"invoice","industry":"manufacturing"},"storage_usage":{"bytes_used":1024,"metadata_bytes_used":256},"tables":[{"data":{"headers":[[{"text_value":"Customer Name"},{"text_value":"Balance"},{"text_value":"Account Created"}]],"rows":[[{"text_value":"Acme Corp"},{"float_value":10230.25},{"text_value":"2023-01-15"}],[{"text_value":"Beta Industries"},{"float_value":8750},{"text_value":"2022-11-03"}],[{"text_value":"Zeta Manufacturing"},{"float_value":13499.99},{"text_value":"2023-06-30"}]]},"description":"Monthly billing for top manufacturing clients","id":"billing_table_1","title":"Customer Billing Info"}],"type":"core"}
type CoreDocument struct {
	// DocumentParts The parts that make up the document.
	DocumentParts []CoreDocumentPart `json:"document_parts"`

	// Id The document ID must be unique within the corpus.
	//
	// Example: Invoice-403
	Id string `json:"id"`

	// Images The images that this document contains.
	Images *[]Image `json:"images,omitempty"`

	// Metadata Arbitrary object of document level metadata. Properties of this object can be used by document filters if defined as a corpus filter attribute.
	//
	// Example: {"lang":"eng","title":"Customer Billing Information"}
	Metadata *map[string]interface{} `json:"metadata,omitempty"`

	// Tables The tables that this document contains.
	Tables *[]Table `json:"tables,omitempty"`

	// Type When the type of the indexed document is `core`, the rest of the object follows this schema. This schema allows precise specification of document parts. Each part translates directly to a search result.
	Type string `json:"type"`
}

// CoreDocumentPart A part of a document. The platform converts this section into an embedding, and it maps directly to a search result. A part is usually a sentence.
type CoreDocumentPart struct {
	// Context The context text for the document part.
	//
	// Example: This document part is part of the table Customer Billing Info.
	Context *string `json:"context,omitempty"`

	// CustomDimensions The custom dimensions as additional weights.
	CustomDimensions *CustomDimensions `json:"custom_dimensions,omitempty"`

	// ImageId The ID of the image that this document part is summarizing.
	//
	// Example: image_1
	ImageId *string `json:"image_id,omitempty"`

	// ImagePartMode How this part is matched at query time.
	//
	// - `text` — matched on its `text`, like any text part.
	// - `image` — matched by visual similarity against image queries for the image referenced by `image_id`; its `text`, if set, also makes the part findable through keyword search.
	// - `image_and_text` — matched against both the referenced image and its `text` together.
	//
	// When omitted, the mode is inferred. On a corpus that does not support image queries, a part is always `text`. Otherwise it defaults to `image` when it references an image and has no `text`, `image_and_text` when it references an image and has `text`, and `text` otherwise.
	//
	//
	// Example: image_and_text
	ImagePartMode *CoreDocumentPartImagePartMode `json:"image_part_mode,omitempty"`

	// Metadata The metadata for a document part. These may be used in metadata filters at query time if filter attributes are configured on the corpus.
	//
	// Example: {"part.rank":9000}
	Metadata *map[string]interface{} `json:"metadata,omitempty"`

	// TableId The ID of the table that this document part is summarizing.
	//
	// Example: billing_table_111
	TableId *string `json:"table_id,omitempty"`

	// Text The text of the document part.
	//
	// Example: This invoice includes customer billing history for Q1.
	Text string `json:"text"`
}

// CoreDocumentPartImagePartMode How this part is matched at query time.
//
// - `text` — matched on its `text`, like any text part.
// - `image` — matched by visual similarity against image queries for the image referenced by `image_id`; its `text`, if set, also makes the part findable through keyword search.
// - `image_and_text` — matched against both the referenced image and its `text` together.
//
// When omitted, the mode is inferred. On a corpus that does not support image queries, a part is always `text`. Otherwise it defaults to `image` when it references an image and has no `text`, `image_and_text` when it references an image and has `text`, and `text` otherwise.
//
// Example: image_and_text
type CoreDocumentPartImagePartMode string

// CorporaSearchTool A corpora search tool that searches through Vectara corpora to find relevant information.
type CorporaSearchTool struct {
	// Category Functional category of the tool (e.g., retrieval, artifacts, indexing, utilities, orchestration).
	Category *string `json:"category,omitempty"`

	// CreatedAt Timestamp when the tool was created.
	CreatedAt *time.Time `json:"created_at,omitempty"`

	// DefaultArgumentOverride Optional hardcoded arguments for tool calls. The key specifies the location in the tool arguments to override. The value specifies what to override with. The agent cannot change these parameters and does not know these values exist.
	//
	// The values can also be dynamic references to context values using $ref with dot notation path syntax:
	// - Static value: "fixed_value" or 123
	// - Dynamic reference: `{"$ref": "session.metadata.field_name"}`
	//
	// References resolve at runtime from context:
	// - session.metadata.* - Access session metadata fields
	// - session.caller.type / .id / .email - The platform-verified identity of the caller who created the session (`user`, `anonymous`, `api_key`, `app_client`, `agent`, or `service_account`. For `user` the `id` is the user's subject, which for a federated identity is the one asserted by the identity provider; for `anonymous` it is the `vis_` visitor id minted by the widget bootstrap; for `api_key` it is the SHA-256 hex digest of the key's secret value, stable per key but not the `aky_` api key id and never returned by `/v2/api_keys`; for `app_client` it is the app client's `client_id`; for `agent` it is the client id of the service account a Vectara-run agent acts as; for `service_account` it is the client id of a Vectara platform job's account, such as an evaluation run, a pipeline, or a simulation. `email` is present only for `user` callers. A session created by an agent reports `agent`). The platform derives it from the authenticated request. A client cannot set it or shadow it through session metadata. It resolves only during session-creation enrichment (`session_enrichment.tool_calls` and the `enrichment_only` tool configurations they name). A reference to it from a tool the agent calls mid-conversation stays unresolved and that call fails. An absent value (no email on the caller, or no authenticated identity) leaves the $ref unresolved and fails the call closed. In an `input_transform` jq expression the same absent value reads as `null` instead, so guard it there.
	// - agent.metadata.* - Access agent metadata fields
	// - agent.secrets.* - Access agent secrets (masked in audit events)
	// - tools.* - Access prior tool outputs (resolved after the dependent tool runs)
	// - inputs.user.latest.text, inputs.user.latest.artifacts[i].artifact_id, .filename, .mime_type, .size_bytes, .purpose - The session's most recent user input: its text and the files uploaded or shared with it, each with the fields of its artifact reference (purpose is set on shared files that have one). text is absent when the input has none, such as files sent without a message. Resolved when the tool runs. A $ref with nothing to read (before the session's first user input, text on an input without text, during session enrichment, or for a tool called from code running in a sandbox) fails to resolve, which fails the tool call unless the $ref has a $default, as in {"$ref": "inputs.user.latest.text", "$default": ""}, whose value is used instead. In a lambda tool's own tool_configurations, inputs.* refs are rejected with 400 when the lambda tool is created, updated, or tested; to use the input there, pass it in through the lambda's own arguments.
	// - currentDate - The current date/time in ISO 8601 format
	//
	// A bracket index may reference another context value. The resolved value becomes the lookup key. The inner path may optionally carry a leading $ root marker:
	// - Indirect reference: `{"$ref": "agent.secrets[session.metadata.user_id]"}` looks up the per-user secret named by `session.metadata.user_id`
	// - Equivalent forms: `agent.secrets[$session.metadata.user_id]` and `agent.secrets[$.session.metadata.user_id]`
	//
	// Example:
	//   `{"query": {"$ref": ".session.metadata.query"}}`
	//
	// To use a literal `"$ref"` value, write `"$$ref"`. The $$ escapes the first $.
	//
	// Example: {"max_results":10}
	DefaultArgumentOverride *map[string]interface{} `json:"default_argument_override,omitempty"`

	// DefaultInputTransform An optional jq expression applied to the tool's input after argument overrides merge with the agent's arguments and before the tool runs.
	// Use this to inject server-side context (session metadata, agent secrets) into the tool input, or to reshape the agent's arguments.
	//
	// The expression receives the standard runtime context: the same `agent`, `session`, `tools`, and `currentDate` values exposed to `argument_override` `$ref`s. It also receives an `args` field that contains the merged tool input.
	// The output of the expression replaces `args` as the tool input.
	// The pre-transform `args` is what appears in audit events (with secrets masked); the post-transform value goes only to the tool.
	// If the expression fails to compile or evaluate, the tool call returns an error to the agent.
	//
	// Examples:
	//   - `.args + { auth: ("Bearer " + .agent.secrets.token) }` — inject a bearer header
	//   - `.args | .corpus_key = .session.metadata.corpus_key` — pull a corpus key from session metadata
	//   - `.args | .query = (.args.query + " " + .session.metadata.query_suffix)` — augment the agent's query
	//
	//
	// Example: .args + { auth: ("Bearer " + .agent.secrets.token) }
	DefaultInputTransform *InputTransform `json:"default_input_transform,omitempty"`

	// DefaultOutputTransform An optional jq expression applied to the tool's JSON output before the agent receives it.
	// Use this to project, filter, or summarize tool output to keep responses concise and on-topic.
	//
	// The expression operates on the tool's response JSON and the result replaces the original output.
	// If the expression fails to compile or evaluate at runtime, the tool call returns an error to the agent so the agent can react.
	//
	// Examples:
	//   - `.results | map({title, url})` — keep only title/url for each result
	//   - `.items[0:5]` — first 5 items
	//   - `del(.debug)` — drop a noisy field
	//
	//
	// Example: .results | map({title, url})
	DefaultOutputTransform *OutputTransform `json:"default_output_transform,omitempty"`

	// Description The description provided to the agent to guide tool selection.
	// This is what the agent sees when deciding which tool to use.
	Description string `json:"description"`

	// DescriptionTemplate Velocity template for generating dynamic tool descriptions. When set, the template renders at runtime to produce the tool description.
	//
	// Available Velocity variables:
	// - `$agent.name` - Agent name
	// - `$agent.metadata` - Agent metadata map
	// - `$session.key` - Session key
	// - `$session.metadata` - Session metadata map
	// - `$currentDate` - Current date/time in ISO 8601 format (e.g., "2025-10-24T15:30:45Z")
	//
	// Example: "Search tool configured for agent $agent.name on $currentDate"
	DescriptionTemplate *ToolDescriptionTemplate `json:"description_template,omitempty"`

	// Documentation User-facing documentation describing the tool and how to configure it for an agent.
	// Intended for developers and administrators browsing the tool catalog.
	// Defaults to the agent-facing description if not explicitly set.
	Documentation *string `json:"documentation,omitempty"`

	// Enabled Whether the tool is currently enabled and available for use.
	Enabled bool `json:"enabled"`

	// Experimental Whether this tool is experimental and may change or be removed without notice.
	Experimental *bool `json:"experimental,omitempty"`

	// Id Unique identifier for a tool.
	//
	// Example: tol_123e4567-e89b-12d3-a456-426614174000
	Id ToolId `json:"id"`

	// InputSchema The schema that defines the expected input structure for the tool.
	InputSchema map[string]interface{} `json:"input_schema"`

	// Lineage The base tool name without version suffix. Groups versioned variants of the same tool together.
	//
	// Example: corpora_search
	Lineage *string `json:"lineage,omitempty"`

	// Name Unique identifier for the tool.
	Name string `json:"name"`

	// OutputSchema The JSON schema that describes the structure of the tool's output. Clients may use it to
	// understand the shape of tool responses and to author `default_output_transform` jq expressions.
	OutputSchema *map[string]interface{} `json:"output_schema,omitempty"`

	// Title Human-readable title of the tool.
	Title *string `json:"title,omitempty"`

	// ToolGroups Groups this tool belongs to. Tools in the same group form a functional set and should be added or removed together by default.
	//
	// Example: ["document_ingestion"]
	ToolGroups *[]string `json:"tool_groups,omitempty"`

	// Type This should always be `corpora_search`.
	//
	// Example: corpora_search
	Type string `json:"type"`

	// UpdatedAt Timestamp when the tool was last updated.
	UpdatedAt *time.Time `json:"updated_at,omitempty"`

	// Version Date-based version identifier in YYYY-MM-DD format. Null for unversioned tools.
	//
	// Example: 2026-02-23
	Version *string `json:"version,omitempty"`
}

