// CreateLambdaToolRequest Request to create a new lambda tool. Lambda tools are user-defined functions that run in a secure, sandboxed environment with Python 3.12.
//
// Input and output schemas are automatically discovered from function parameter type annotations in your code.
//
// When `tool_configurations` is set, each configured tool is callable from the lambda tool's code as a
// function on the built-in `tool` module. `$ref` values in those configurations resolve against the hosting agent
// and session at execution time.
type CreateLambdaToolRequest struct {
	// Code The Python 3.12 code for the function.
	//
	// **Required**: Must define a `process()` entry point function. Use type annotations on parameters for automatic schema discovery.
	//
	// **Parameters**: Passed as keyword arguments matched to the function signature.
	//
	// **Return types**: Can return any JSON-serializable type (strings, numbers, booleans, lists, or objects).
	//
	// **Parameter Descriptions**: Use docstrings to provide descriptions for parameters (Google, NumPy, ReST, and Epydoc styles are supported). The platform extracts these descriptions and includes them in the input schema. This gives agents better context about how to use each parameter.
	//
	// **Example with Google-style docstring:**
	// ```python
	// def process(order_count: int, total_revenue: float, days_active: int = 1) -> dict:
	//     """Calculate customer engagement score.
	//
	//     Args:
	//         order_count: The number of orders placed by the customer.
	//         total_revenue: Total revenue in USD from the customer.
	//         days_active: Number of days the customer was active (default: 1).
	//
	//     Returns:
	//         A dict with the calculated score.
	//     """
	//     score = (order_count * 10 + total_revenue * 0.1) / days_active
	//     return {'score': round(score, 2)}
	// ```
	//
	// This produces an input schema with descriptions:
	// ```json
	// {
	//   "type": "object",
	//   "properties": {
	//     "order_count": {
	//       "type": "integer",
	//       "description": "The number of orders placed by the customer."
	//     },
	//     "total_revenue": {
	//       "type": "number",
	//       "description": "Total revenue in USD from the customer."
	//     },
	//     "days_active": {
	//       "type": "integer",
	//       "description": "Number of days the customer was active (default: 1)."
	//     }
	//   },
	//   "required": ["order_count", "total_revenue"]
	// }
	// ```
	//
	// **Example: Returning a number**
	// ```python
	// def process(x: int, y: int) -> int:
	//     return x + y
	// ```
	//
	// **Example: Returning a string**
	// ```python
	// def process(name: str) -> str:
	//     return f"Hello, {name}!"
	// ```
	//
	// **Example: Returning a boolean**
	// ```python
	// def process(value: int, threshold: int) -> bool:
	//     return value > threshold
	// ```
	//
	// **Example: Returning a list**
	// ```python
	// from typing import List
	//
	// def process(items: List[str]) -> List[str]:
	//     return sorted(items)
	// ```
	//
	// **Example: Returning an object (dict)**
	// ```python
	// def process(order_count: int, total_revenue: float, days_active: int = 1) -> dict:
	//     score = (order_count * 10 + total_revenue * 0.1) / days_active
	//     return {'score': round(score, 2), 'rating': 'high' if score > 100 else 'low'}
	// ```
	//
	// For complex types, use the `typing` module:
	//
	// ```python
	// from typing import List
	//
	// def process(items: List[str], count: int) -> dict:
	//     return {'total': len(items) * count}
	// ```
	//
	// **Object parameters must use TypedDict**: Validation rejects bare `dict` and `Dict[K, V]` parameters. All object-typed parameters must use `TypedDict` to define explicit fields. This ensures the agent receives a clear schema for each parameter.
	//
	// ```python
	// from typing import TypedDict, Optional
	//
	// class Adjustment(TypedDict, total=False):
	//     monthly_premium: float
	//     target_income_age: int
	//     illustrated_rate: float
	//
	// def process(client_id: str, adjustment: Adjustment) -> dict:
	//     return {"client_id": client_id, "adjustment": adjustment}
	// ```
	//
	// TypedDict supports inheritance, `Optional` fields, nested TypedDicts, and `total=False` to make all fields optional.
	//
	// **Constraining parameters to specific values with Literal**: Use `Literal` to restrict a parameter to a fixed set of allowed values. This generates an `enum` constraint in the JSON schema, helping the agent choose valid options.
	//
	// ```python
	// from typing import Literal
	//
	// def process(status: Literal["active", "inactive", "pending"], priority: Literal[1, 2, 3]) -> dict:
	//     return {"status": status, "priority": priority}
	// ```
	//
	// When `tool_configurations` is set, the code can call those tools through the built-in `tool` module; see the `tool_configurations` field.
	//
	//
	// Example: def process(order_count: int, total_revenue: float, days_active: int = 1) -> dict:
	//     score = (order_count * 10 + total_revenue * 0.1) / days_active
	//     return {'score': round(score, 2)}
	Code string `json:"code"`

	// Description A detailed description of what the function does, when to use it, and what it returns.
	//
	// Example: Calculate a customer score based on order history and revenue. Returns a score between 0-100.
	Description string `json:"description"`

	// ExecutionConfiguration Execution configuration for the function.
	ExecutionConfiguration *ExecutionConfiguration `json:"execution_configuration,omitempty"`

	// Language The programming language. Currently only 'python' (Python 3.12) is supported.
	//
	// Example: python
	Language *CreateLambdaToolRequestLanguage `json:"language,omitempty"`

	// Name The unique name of the tool (used as the function identifier).
	//
	// Example: calculate_customer_score
	Name string `json:"name"`

	// Title Human-readable title of the tool displayed in the UI.
	//
	// Example: Customer Score Calculator
	Title *string `json:"title,omitempty"`

	// ToolConfigurations Named configurations of other tools this lambda may invoke from its Python code through the built-in `tool` module. Each entry is exposed as
	// `tool.<name>(param=value)`; `tool.list()` returns their names and schemas, and failures raise `tool.ToolError`.
	//
	// `$ref` values inside `argument_override` resolve against the hosting agent and session at execution time — `agent.metadata.*`, `agent.secrets.*`, and
	// `session.metadata.*` only. These configurations are private to the tool: they never appear on the hosting agent's callable tools, and their calls produce
	// no session events.
	//
	// A configured tool may itself be a lambda with its own `tool_configurations`; there is no fixed nesting depth. A session wires at most 1,024 lambda scopes; lambdas past that cap run without their `tool` and `artifacts` bridges. One run allows at most 50 concurrent and 10,000 total in-code tool invocations across every composed lambda; a lambda that reappears on its own composition path is wired with no composed tools, so its `tool.*` calls fail rather than recurse.
	//
	// Each configuration name is how the code calls it (`tool.<name>`), so it must be a valid identifier: a letter followed by letters, digits, or
	// underscores.
	//
	// See `POST /v2/tools/test` for exercising these calls without persisting the tool.
	//
	//
	// Example: {"fetch_status":{"argument_override":{"url":"https://status.example.com/api/health"},"type":"web_get"}}
	ToolConfigurations *map[string]AgentToolConfiguration `json:"tool_configurations,omitempty"`

	// Type This should always be `lambda`.
	//
	// Example: lambda
	Type string `json:"type"`
}

