// CronScheduleConfiguration Configuration for cron-based schedule execution.
type CronScheduleConfiguration struct {
	// CronExpression Cron expression that specifies when the schedule executes.
	//
	// Uses standard 5-field cron format:
	// ┌───────────── minute (0-59)
	// │ ┌───────────── hour (0-23)
	// │ │ ┌───────────── day of month (1-31)
	// │ │ │ ┌───────────── month (1-12)
	// │ │ │ │ ┌───────────── day of week (0-6, Sunday=0)
	// │ │ │ │ │
	// * * * * *
	//
	// Special characters:
	// - * : Any value
	// - , : List (e.g., "1,15" for 1st and 15th)
	// - - : Range (e.g., "1-5" for Monday-Friday)
	// - / : Step (e.g., "*/15" for every 15 units)
	//
	// The schedule must not fire more frequently than once per hour (PT1H).
	//
	// Common examples:
	// - "0 9 * * *": Every day at 9:00 AM
	// - "0 9 * * 1-5": Weekdays at 9:00 AM
	// - "0 * * * *": Every hour
	// - "0 */6 * * *": Every 6 hours
	// - "0 0 1 * *": First day of every month at midnight
	// - "0 0 * * 0": Every Sunday at midnight
	//
	// Tool for testing: https://crontab.guru/
	//
	//
	// Example: 0 9 * * *
	CronExpression string `json:"cron_expression"`

	// Type The type of schedule.
	//
	// Example: cron
	Type CronScheduleConfigurationType `json:"type"`
}

// CronScheduleConfigurationType The type of schedule.
//
// Example: cron
type CronScheduleConfigurationType string

// CronTriggerConfiguration Runs the pipeline on a cron schedule.
type CronTriggerConfiguration struct {
	// Expression A 5-field cron expression (minute, hour, day-of-month, month, day-of-week) in UTC.
	//
	// Example: 0 */6 * * *
	Expression string `json:"expression"`

	// Type Example: cron
	Type string `json:"type"`
}

