// DiscoverLLMsRequest Request to probe an external LLM provider endpoint and return the model configurations most likely to work. Nothing is persisted. Submit a returned candidate to `POST /v2/llms` to create the LLM.
type DiscoverLLMsRequest struct {
	// Auth The credential to authenticate the probe with. Accepts any variant that any provider supports. Omit for an unauthenticated endpoint (e.g. a self-hosted vLLM server), in which case `uri` is required.
	Auth *LLMAuth `json:"auth,omitempty"`

	// Headers Additional HTTP headers to send with the probe requests.
	Headers *map[string]string `json:"headers,omitempty"`

	// TestModelParameters Extra parameters passed to the live verification call (e.g. `max_tokens` for providers that require it).
	//
	// Example: {"max_tokens":512}
	TestModelParameters *map[string]interface{} `json:"test_model_parameters,omitempty"`

	// Type Optional provider-type hint. When set, discovery is restricted to that provider; a hint that contradicts what the credential and URI imply fails with HTTP 422. When omitted, the platform infers candidate provider types from the credential shape and the URI host, and probes both the chat-completions and responses dialects for a generic OpenAI-compatible host.
	Type *LLMType `json:"type,omitempty"`

	// Uri The provider endpoint URI: an http or https URL including a host. Accepts a base URL, a full chat/completions URL, or a Vertex `generateContent` URL; each is reduced to the provider's base endpoint. Optional when the credential itself identifies the provider: Anthropic (`sk-ant-…`) and OpenAI (`sk-…`) API keys, Bedrock credentials (endpoint derived from the region), `vertex_service_account`/`vertex_access_token` credentials (endpoint derived from the project and region), and the Gemini `api_key` credential (endpoint defaults to Google AI Studio). Required for any other credential, including the Gemini `service_account` credential, which declares no project or region.
	//
	// Example: https://api.openai.com/v1/chat/completions
	Uri *string `json:"uri,omitempty"`
}

// DiscoverLLMsResponse The model configurations discovered by probing the endpoint, most-likely-to-work first.
type DiscoverLLMsResponse struct {
	// Candidates Discovered configurations, one per (provider type, model). Candidates that were successfully live-tested (`verified: true`) are listed first. Submit any candidate's fields — together with the same credential you passed in — to `POST /v2/llms` to create the LLM.
	Candidates []DiscoveredLLM `json:"candidates"`
}

// DiscoveredLLM A single likely-working LLM configuration discovered by probing an endpoint.
type DiscoveredLLM struct {
	// Capabilities Capabilities inferred for `model` from its name and provider type.
	Capabilities *LLMCapabilities `json:"capabilities,omitempty"`

	// Model The provider-specific model identifier this candidate configures.
	Model string `json:"model"`

	// Type The provider type to use when creating this LLM.
	Type LLMType `json:"type"`

	// Uri The endpoint URI to use when creating this LLM, normalized and rebuilt for this candidate's dialect (for example `…/v1/chat/completions` for `openai-compatible` and `…/v1/responses` for `openai-responses`). Absent for providers whose endpoint is derived from the credential rather than a URL — Anthropic on Bedrock (region-derived) and, where no base URI was supplied, Vertex.
	//
	// Example: https://api.openai.com/v1/chat/completions
	Uri *string `json:"uri,omitempty"`

	// VerificationError When `verified` is false, the reason this model's live test failed. When every live test against the candidate's endpoint failed, the endpoint-wide failure is reported instead. Null for an untested candidate on a healthy endpoint.
	VerificationError *string `json:"verification_error,omitempty"`

	// Verified Whether a live generation round-trip against this exact `model` succeeded. At most three models per detected endpoint are live-tested; other candidates sharing a healthy endpoint are returned with `verified` false and no `verification_error`, and are expected to work.
	Verified bool `json:"verified"`
}

