// FluidtopicsSourceConfiguration Configuration for ingesting content from a Fluid Topics tenant via the Knowledge Hub REST API.
type FluidtopicsSourceConfiguration struct {
	// ApiKey Fluid Topics API key, sent as an HTTP Bearer authorization token. Requires read access to
	// the configured content, plus administration scope when incremental runs read dataflow
	// reports. Generate one in the Fluid Topics administration interface under Integrations, API
	// keys — see
	// https://doc.fluidtopics.com/r/Fluid-Topics-Configuration-and-Administration-Guide/Configure-a-Fluid-Topics-tenant/Integrations/API-keys.
	// Encrypted at rest and not returned in responses.
	ApiKey *string `json:"api_key,omitempty"`

	// BaseUrl Base URL of the Fluid Topics tenant.
	//
	// Example: https://example.fluidtopics.net
	BaseUrl string `json:"base_url"`

	// ContentScope Which Fluid Topics content layer to ingest:
	// - `documents`: enumerates standalone documents.
	// - `topics`: enumerates the topics within maps, iterating map by map so each topic carries
	//   its parent map's identity and classification.
	// - `maps`: enumerates maps, emitting one record each.
	//
	// Under `maps`, `query` is ignored. `filters`, `locale`, `include_sources`, and
	// `exclude_sources` apply, matched against each map's metadata.
	ContentScope *FluidtopicsSourceConfigurationContentScope `json:"content_scope,omitempty"`

	// DocumentFetchModes How document bodies are fetched in the `documents` scope, as a map of MIME type to fetch
	// mode. Keys match a document's MIME type (`ft:mimeType`) exactly (`application/pdf`), by
	// prefix (`image/*`), or `*` as the catch-all default. Types matching no key use
	// `extracted_text`, the behavior when this map is unset. Ignored when `content_scope` is
	// `topics`.
	//
	//
	// Example: {"application/pdf":"original_file","video/*":"metadata_only"}
	DocumentFetchModes *map[string]FluidtopicsDocumentFetchMode `json:"document_fetch_modes,omitempty"`

	// ExcludeSources Fluid Topics source ids (`ft:sourceId`, for example `drupal` or `khoros`) whose records are
	// excluded from ingestion, even when they also match `include_sources`. Applied to every
	// ingestion path regardless of `query` or `filters`. Empty (the default) excludes nothing.
	//
	//
	// Example: ["drupal","khoros"]
	ExcludeSources *[]string `json:"exclude_sources,omitempty"`

	// Filters Restricts ingestion to records matching the given Fluid Topics metadata, as a map of metadata
	// key to the list of accepted values. For example `{"Disclosure": ["Public"]}` ingests only
	// public content. When unset, no metadata filter is applied. Under `content_scope: maps` the
	// reserved key `id` matches the map's own identifier, so `{"id": ["<map_id>"]}` restricts a run
	// to a single map.
	//
	//
	// Example: {"Disclosure":["Public"]}
	Filters *map[string][]string `json:"filters,omitempty"`

	// IncludeSources Fluid Topics source ids (`ft:sourceId`) to ingest. A record whose source is not listed is
	// skipped. Applied to every ingestion path regardless of `query` or `filters`. Empty (the
	// default) ingests every source.
	//
	//
	// Example: ["ud"]
	IncludeSources *[]string `json:"include_sources,omitempty"`

	// Locale Restricts ingestion to a single content locale (Fluid Topics `contentLocale`), for example
	// `en-US`. When unset, all locales are ingested. Records that carry no locale metadata are
	// never excluded by this filter.
	//
	//
	// Example: en-US
	Locale *string `json:"locale,omitempty"`

	// Query Search query used to select the content to ingest. Defaults to `*` (all content).
	// Ignored when `content_scope` is `maps`. In the `documents` and `topics` scopes, a query
	// other than `*` makes incremental runs re-enumerate the query's results and filter by
	// last-edition date, so metadata-only changes are not detected.
	//
	//
	// Example: *
	Query *string `json:"query,omitempty"`

	// Type Example: fluidtopics
	Type *string `json:"type,omitempty"`
}

// FluidtopicsSourceConfigurationContentScope Which Fluid Topics content layer to ingest:
//   - `documents`: enumerates standalone documents.
//   - `topics`: enumerates the topics within maps, iterating map by map so each topic carries
//     its parent map's identity and classification.
//   - `maps`: enumerates maps, emitting one record each.
//
// Under `maps`, `query` is ignored. `filters`, `locale`, `include_sources`, and
// `exclude_sources` apply, matched against each map's metadata.
type FluidtopicsSourceConfigurationContentScope string

// FunctionDefinition Definition of a function to be executed as a tool in a sandboxed environment.
//
// **Python Environment:**
// - Python version: 3.12
// - Execution: isolated, with no network access
// - **Preinstalled packages**: the standard library plus data and document packages including `numpy`, `pandas`, `python-calamine`, `openpyxl`, `xlrd`, `xlsxwriter`, `python-pptx`, and `python-docx`. Import `python-calamine` as `python_calamine`, `python-pptx` as `pptx`, and `python-docx` as `docx`.
// - Memory: fixed by the execution environment and not configurable per function
// - Execution timeout: 30 seconds (configurable up to 300 seconds)
// - File system access: a writable temporary workspace, discarded after each execution
// - No custom package installation supported
//
// **Type Annotations:**
// - Use type annotations for automatic input/output schema discovery
// - Supported typing constructs: `List`, `Dict`, `Optional`, `Union`, `Literal`
// - Import from `typing` module when using complex types
//
// **Docstring Parameter Descriptions:**
// - Use docstrings to provide descriptions for parameters (Google, NumPy, ReST, and Epydoc styles are supported)
// - The platform extracts parameter descriptions and includes them in the input schema
// - This gives agents better context about how to use each parameter
type FunctionDefinition struct {
	// Code The function code.
	//
	// **Required**: Must define a `process()` entry point function. Use type annotations on parameters for automatic schema discovery.
	//
	// Parameters are passed as keyword arguments matched to the function signature.
	//
	//
	// Example: def process(data: list, threshold: float = 0):
	//     filtered = [x for x in data if x > threshold]
	//     return {
	//         'count': len(filtered),
	//         'average': sum(filtered) / len(filtered) if filtered else 0,
	//         'filtered_data': filtered
	//     }
	Code string `json:"code"`

	// ExecutionConfiguration Execution configuration for the function.
	ExecutionConfiguration *ExecutionConfiguration `json:"execution_configuration,omitempty"`

	// Language The programming language of the function. Currently only Python 3.12 is supported.
	//
	// Example: python
	Language FunctionDefinitionLanguage `json:"language"`

	// ValidationErrors List of validation errors if the code is invalid.
	ValidationErrors *[]string `json:"validation_errors,omitempty"`

	// ValidationStatus The validation status of the code.
	//
	// Example: valid
	ValidationStatus *FunctionDefinitionValidationStatus `json:"validation_status,omitempty"`
}

// FunctionDefinitionLanguage The programming language of the function. Currently only Python 3.12 is supported.
//
// Example: python
type FunctionDefinitionLanguage string

// FunctionDefinitionValidationStatus The validation status of the code.
//
// Example: valid
type FunctionDefinitionValidationStatus string

