// MetricDescriptor Metadata about a registered metric. `type` selects the concrete variant.
type MetricDescriptor struct {
	union json.RawMessage
}

// MetricDescriptorBase Common metadata fields shared by every metric descriptor regardless of type.
type MetricDescriptorBase struct {
	// Category The top-level grouping for this metric.
	//
	// Example: agent
	Category string `json:"category"`

	// Description A human-readable description of what the metric measures.
	Description string `json:"description"`

	// Dimensions The names of the dimensions this metric is broken down by. Filter on them with the `dimensions` query parameter when querying the metric. On a custom metric these are the dimension names declared in its definition.
	//
	// Example: ["agent_keys"]
	Dimensions []string `json:"dimensions"`

	// DisplayName A short human-readable name for this metric, suitable as a chart title or list
	// label.
	//
	//
	// Example: Agent turn duration percentiles
	DisplayName string `json:"display_name"`

	// Labels Deprecated alias for `dimensions`; identical value. Use `dimensions`.
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	Labels []string `json:"labels"`

	// Name The unique name of the metric, used as the path parameter to query it. Custom metric names start with `custom.`.
	//
	// Example: agent.trace.duration_ms
	Name string `json:"name"`

	// Origin Who provides the metric.
	Origin MetricOrigin `json:"origin"`

	// Unit The unit of measure for the metric values, when applicable.
	//
	// Example: ms
	Unit *string `json:"unit,omitempty"`
}

// MetricOrigin Who provides a metric. New values may be added; treat unknown values as opaque.
//
// * `system`: the platform provides the metric. It cannot be updated or deleted.
// * `custom`: the account created the metric from its agent traces.
//
// Example: system
type MetricOrigin string

// MetricSeries A metric query result. A single series of points whose shape varies by metric type.
type MetricSeries struct {
	union json.RawMessage
}

// MetricSeriesBase Common properties shared by all metric series types.
type MetricSeriesBase struct {
	// BinSizeSeconds The width of each time bin in the returned series, in seconds. The platform chooses it from the requested time range and `max_bins`. When `max_bins` is 1, it is the width of the requested window after rounding `start` down and `end` up to the nearest five-minute boundary.
	BinSizeSeconds int32 `json:"bin_size_seconds"`

	// DimensionValues The dimension values identifying this series, keyed by dimension name. Echoes the `dimensions` filter supplied in the request. A dimension absent from the map was not filtered, so the series merges every value of it.
	DimensionValues map[string][]string `json:"dimension_values"`

	// Labels Deprecated alias for `dimension_values`; identical value. Use `dimension_values`.
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	Labels map[string][]string `json:"labels"`

	// Metric The descriptor of the metric this series describes, as listed in the catalog. Carries the unit, the dimension names, and the percentile ranks or bin ranges needed to interpret the points.
	Metric MetricDescriptor `json:"metric"`

	// MetricName The name of the metric this series describes.
	MetricName string `json:"metric_name"`
}

// MultipartInputEvent Input event with file uploads and optional message parts. Sent as multipart form data.
type MultipartInputEvent struct {
	// Behavior Controls how the input is processed when the session is already running.
	// - `steer`: Insert the message as soon as possible on the next iteration of the agent loop.
	// - `follow_up`: Insert the message after the current agent loop finishes, as a follow-up turn.
	//   Follow-up inputs are consumed one at a time: after each follow-up turn completes, the next
	//   queued follow-up is processed. This ensures each follow-up gets a full agent loop iteration.
	Behavior *InputBehavior `json:"behavior,omitempty"`

	// EntryStep Name of the step the agent enters before processing this input. Must be a key in the agent's `steps` map or the agent's `first_step_name`. When omitted, the session resumes at its `current_step_name`.
	//
	//
	// Example: triage
	EntryStep *string `json:"entry_step,omitempty"`

	// Files Files to upload to the agent session. Any file type is accepted.
	// What the agent can do with the file depends on the tools available to it.
	Files *[]openapi_types.File `json:"files,omitempty"`

	// Message Deprecated: use messages instead.
	// Plain text input message to accompany the file upload.
	// If both message and messages are provided, messages takes precedence and message is ignored.
	//
	//
	// Example: I need help with my widget installation
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	Message *string `json:"message,omitempty"`

	// Messages List of inputs that make up this event. Each entry is an AgentInput selected by "type: text" for plain text content (default), or "skill" to invoke a skill by name. Sent as a JSON-encoded string in the multipart form. If omitted, falls back to the deprecated "message" field as a single text input.
	//
	//
	// Example: [{"content":"Review this file","type":"text"},{"skill_name":"code_review","type":"skill"}]
	Messages *[]AgentInput `json:"messages,omitempty"`

	// Since An event ID cursor. When provided and the session is currently running, the response includes all events created after this event ID. The new input is queued and processed according to the behavior field. Use the special value "start" to receive all events from the beginning of the session, including the input message itself.
	//
	//
	// Example: start
	Since *string `json:"since,omitempty"`

	// StreamResponse Whether to stream the response.
	StreamResponse *bool `json:"stream_response,omitempty"`

	// SurfaceDescription Identifies the surface submitting this input, such as a connector. The `(type, id)` pair identifies the surface within the session; repeat submissions from the same pair are treated as one surface. All fields are optional; a caller that omits `type` is treated as an `api` surface.
	SurfaceDescription *SurfaceDescription `json:"surface_description,omitempty"`
}

// MyGoogleDriveScope Ingests from a single user's My Drive via Google Workspace domain-wide delegation. Requires
