// NextStep A conditional transition to another step.
type NextStep struct {
	// Condition UserFn expression evaluating to boolean.
	// Uses the `get()` function with JSONPath to access the step transition context.
	// See https://docs.vectara.com/docs/reference/userfn-language for the UserFn language reference.
	// Omit for catch-all/default routing.
	//
	// The context available to `get()` has the following shape:
	// ```
	// {
	//   "agent": {
	//     "name": "...",
	//     "key": "...",
	//     "description": "...",
	//     "metadata": { ... }
	//   },
	//   "session": {
	//     "key": "...",
	//     "name": "...",
	//     "description": "...",
	//     "metadata": { ... }
	//   },
	//   "currentDate": "2024-01-15T10:35:00Z",
	//   "inputs": {
	//     "user": {
	//       "latest": {
	//         "text": "...",
	//         "artifacts": [{ "artifact_id": "...", "filename": "...", "mime_type": "...", "size_bytes": 0 }]
	//       }
	//     }
	//   },
	//   "tools": {
	//     "<tool_config_name>": {
	//       "outputs": {
	//         "latest": { ... }
	//       }
	//     }
	//   },
	//   "output": { "text": "..." }
	// }
	// ```
	//
	// - `$.agent.key`, `$.agent.name`, `$.agent.description`, `$.agent.metadata.<key>` — the agent
	// - `$.session.key`, `$.session.name`, `$.session.description`, `$.session.metadata.<key>` — the session
	// - `$.currentDate` — the evaluation time, ISO 8601
	// - `$.inputs.user.latest.text`, `$.inputs.user.latest.artifacts[i].<field>` — the session's most recent user input and the files uploaded or shared with it; each file has the fields of its artifact reference, including the `purpose` a sharer gave. `text` is absent when the input has none, `artifacts` is an empty array when it has no files, and `$.inputs.user.latest` is absent before the session's first user input
	// - `$.tools.<tool_config_name>.outputs.latest.<field>` — latest tool output fields, present only for tools that produced output
	// - `$.output.text` — agent text output (when output_parser is `default`)
	// - `$.output.<field>` — agent structured output fields (when output_parser is `structured`)
	//
	//
	// Example: get('$.output.intent') == 'sales'
	Condition *string `json:"condition,omitempty"`

	// StepName Name of the step to transition to.
	// Must reference a step defined in the agent's steps list.
	//
	//
	// Example: sales_handler
	StepName string `json:"step_name"`
}

// NoneReranker A placeholder reranker that does not modify the original search results ordering.
type NoneReranker struct {
	// Limit The maximum number of results to return after the reranking process. When you apply a reranker, it performs these steps:
	// 1. Reranks all input results according to its algorithm.
	// 2. Sorts the reranked results by their new scores.
	// 3. Returns the top N results, where N is the value of this limit.
	// Note: This limit applies per reranking stage. In a chain of rerankers, each reranker can have its own limit. This can reduce the number of results at each stage.
	Limit *int32 `json:"limit,omitempty"`

	// Type When the type is `none`, the search applies no reranking.
	Type *string `json:"type,omitempty"`
}

