// Pipeline A pipeline is an automated data flow. It sends all data from a source system to an agent
// for the agent to act on per its instructions. Each source record creates a new agent
// session. The agent has full autonomy to decide what to do with each piece of data — index
// it into a corpus, extract structured information, route it, or discard it.
//
// This is distinct from an **agent schedule**, which is a recurring single execution of an
// agent with a fixed message. A schedule creates one session per trigger. A pipeline creates
// one session per source record.
//
// This is also distinct from an **agent connector** (e.g. Slack), which is a bidirectional
// integration for interactive chat with an agent. A pipeline is a one-directional automated
// flow of all data through an agent.
type Pipeline struct {
	// CreatedAt When the pipeline was created.
	CreatedAt time.Time `json:"created_at"`

	// Description A description of what this pipeline does.
	//
	// Example: Ingests legal contracts from SharePoint and indexes them into the legal corpus.
	Description *string `json:"description,omitempty"`

	// Enabled Whether the pipeline is enabled. Disabled pipelines do not run on their trigger schedule.
	Enabled bool `json:"enabled"`

	// Key The unique key for the pipeline. You can provide the key, or the platform generates one.
	//
	// Example: sharepoint-legal-ingest
	Key PipelineKey `json:"key"`

	// Metadata Arbitrary key-value metadata for the pipeline.
	Metadata *map[string]string `json:"metadata,omitempty"`

	// Name The human-readable name of the pipeline.
	//
	// Example: SharePoint Legal Docs Ingest
	Name PipelineName `json:"name"`

	// ProcessingOptions Per-pipeline processing options. Omitted when the service defaults apply.
	ProcessingOptions *PipelineProcessingOptions `json:"processing_options,omitempty"`

	// Source The source system to ingest data from.
	Source PipelineSource `json:"source"`

	// Status The current operational status of the pipeline.
	Status PipelineStatus `json:"status"`

	// StatusMessage Human-readable status details, such as an error description.
	StatusMessage *string `json:"status_message,omitempty"`

	// SyncMode How the pipeline syncs data from the source.
	// - `incremental`: Only process records that are new, changed, or deleted since the last watermark.
	// - `full_refresh`: Process all records the source lists on each run. Source-reported deletions are not processed.
	SyncMode PipelineSyncMode `json:"sync_mode"`

	// Transform Defines how source data is processed. Currently only agent transforms are supported.
	Transform PipelineTransform `json:"transform"`

	// Trigger Defines when the pipeline runs.
	Trigger PipelineTrigger `json:"trigger"`

	// UpdatedAt When the pipeline was last updated.
	UpdatedAt *time.Time `json:"updated_at,omitempty"`

	// Watermark The current incremental sync watermark. Null if the pipeline has never run.
	Watermark *PipelineWatermark `json:"watermark,omitempty"`
}

// PipelineDeadLetterEntry A record that failed processing during a pipeline run. Dead letters are pipeline-scoped.
// If the same source record fails across multiple runs, the existing entry is updated, not
// duplicated. Resolved dead letters are deleted.
