// SentenceChunkingStrategy Sets a chunking strategy that creates one chunk per sentence. This is the default strategy used when no chunking strategy is specified.
type SentenceChunkingStrategy struct {
	// PreserveCodeBlocks Keeps markdown code blocks intact. Code blocks in the section text (fenced with ``` or ~~~, or indented by four spaces) become their own chunks. A code block longer than 4096 characters splits at line boundaries, preferring blank lines; a single line that does not fit together with the chunk's prefix and fence markers is split mid-line. Each code chunk is prefixed with the section title, and the first chunk of a block also with the paragraph that introduces it. Code chunks carry `"vectara": {"part_kind": "code"}` in their metadata, merged into any `vectara` object the section metadata already has. Text outside code blocks is chunked as usual by this strategy. Supported by `createCorpusDocument` for structured documents; `uploadFile` returns a 400 with a field error on `chunking_strategy` when this is `true`.
	PreserveCodeBlocks *bool `json:"preserve_code_blocks,omitempty"`

	// Type When setting the type to sentence_chunking_strategy, the platform creates one chunk per sentence.
	Type *string `json:"type,omitempty"`
}

