// SessionEnrichmentConfig Tool calls run at session creation to populate the new session's metadata before the agent's first turn. Each call invokes one of the agent's enrichment-only tool configurations and writes its output into the session metadata. The agent, run conditions, and routing can then read values fetched or computed at session start. Enrichment tools are ordinary entries in the agent's tool_configurations marked enrichment_only, so they are never exposed to the agent's LLM. Enrichment runs for every session the agent creates regardless of trigger, including the API, chat connectors, and schedules. Independent calls run in parallel and a call may consume an earlier call's output. Enrichment is fail-closed: unless a call sets continue_on_error, a failed call aborts session creation and no session is created. The abort status names the failure: 422 for an invalid configuration or a failed transform, 502 for a tool failure, and 504 for a timeout. A jq error raised by the called tool configuration's input_transform or output_transform is a call failure like any other: continue_on_error skips it, and otherwise its message is returned in the error response's messages array.
type SessionEnrichmentConfig struct {
	// Enabled When false, enrichment does not run and sessions are created with the metadata provided by the caller.
	Enabled *bool `json:"enabled,omitempty"`

	// ToolCalls Ordered tool calls run at session creation. Independent calls run in parallel. A call that references another call's output runs after it.
	ToolCalls *[]SessionEnrichmentToolCall `json:"tool_calls,omitempty"`
}

// SessionEnrichmentToolCall A single tool call run during session enrichment. It names one of the agent's enrichment-only tool configurations and supplies the arguments to invoke it with. The tool's own configuration, including its argument defaults and output_transform, lives on the tool configuration rather than on the call. Enrichment runs with no model to fill arguments in. The arguments must therefore include every required parameter of the called tool, either as a literal value or as a reference to an earlier call's output. A call that omits a required parameter is rejected when the agent is created or updated.
type SessionEnrichmentToolCall struct {
	// Arguments Arguments to invoke the tool with. These may set only the parameters that the tool definition does not already fix through its own configured argument_override. A parameter fixed by the tool cannot be set per call, so naming one here is rejected when the agent is created or updated. Enrichment runs with no LLM to fill arguments in. These arguments, together with the parameters fixed by the tool, must cover every required parameter of the tool. Each value is either a literal or a `$ref` object that resolves against session or agent metadata, the agent's secrets as `agent.secrets.<name>`, the session secrets supplied on the create request as `session.secrets.<name>`, or an earlier call's output as `tools.<tool>.outputs.latest`. Session creation fails with 422 if a `$ref` names a secret that is not on the agent or in the create request, unless the `$ref` supplies a `$default`, in which case the default value is used instead.
	Arguments *map[string]interface{} `json:"arguments,omitempty"`

	// ContinueOnError When true a failure of this call is ignored and its target is left unset. Otherwise a call failure aborts session creation.
	ContinueOnError *bool `json:"continue_on_error,omitempty"`

	// MetadataTargetPath Dotted metadata path the tool's output is written to, after the tool's own configured output_transform is applied. Outputs are written to the session metadata in call order. A later write to a path replaces any value written earlier at that path. A call without a target path is compute only, so later calls can reference its output but nothing is written to the metadata. Session metadata is returned unmasked on reads: a tool output or transform that writes a resolved secret value makes that secret readable in the session's metadata.
	MetadataTargetPath *string `json:"metadata_target_path,omitempty"`

	// TimeoutSeconds Seconds the call may run before it is treated as a failed call.
	TimeoutSeconds *int `json:"timeout_seconds,omitempty"`

	// Tool Name of the tool configuration to call. Must name one of the agent's tool_configurations whose enrichment_only is true. A later tool call references an earlier call's output as tools.<tool>.outputs.latest.
	Tool string `json:"tool"`
}

