// SurfaceDescription Identifies the surface submitting this input, such as a connector. The `(type, id)` pair identifies the surface within the session; repeat submissions from the same pair are treated as one surface. All fields are optional; a caller that omits `type` is treated as an `api` surface.
type SurfaceDescription struct {
	// Id An identifier for this surface within its `type`, e.g. a connector id. Combined with `type` to identify the surface within the session.
	//
	// Example: con_slack_support
	Id *string `json:"id,omitempty"`

	// Include When true, the agent is told which listeners — surfaces currently streaming this session — will see this turn's response.
	Include *bool `json:"include,omitempty"`

	// Type The kind of surface the input came from, so the agent knows where its reply will be seen and can shape it for that surface — a free-form label, not a fixed set. Connectors send "slack", "gchat", or "zoom"; API callers may send a label describing their own surface. Treated as "api" when omitted.
	//
	// Example: slack
	Type *string `json:"type,omitempty"`
}

