// TestLambdaToolRequest Request to test a Lambda tool before creating it.
//
// Use this endpoint to:
// - Validate Python code syntax and security constraints
// - Discover input/output schemas from type annotations
// - Test execution with sample input
// - Verify schema compatibility
type TestLambdaToolRequest struct {
	// Code The Python 3.12 code for the function. Must define a `process()` entry point.
	// Object parameters must use `TypedDict`; validation rejects bare `dict` and `Dict[K, V]` parameters.
	// See the `code` field on `CreateLambdaToolRequest` for full details and examples.
	//
	//
	// Example: def process(order_count: int, total_revenue: float) -> dict:
	//     score = order_count * 10 + total_revenue * 0.1
	//     return {'score': round(score, 2)}
	Code string `json:"code"`

	// ExecutionConfiguration Execution configuration for the function.
	ExecutionConfiguration *ExecutionConfiguration `json:"execution_configuration,omitempty"`

	// Language The programming language. Currently only 'python' (Python 3.12) is supported.
	//
	// Example: python
	Language *TestLambdaToolRequestLanguage `json:"language,omitempty"`

	// StreamResponse When true, the response is streamed as Server-sent Events. While the test runs the platform sends zero or more `heartbeat` events, then exactly one terminal `result` event carrying the same object the non-streaming response returns. A platform failure after the stream has started closes the connection without a `result`.
	StreamResponse *bool `json:"stream_response,omitempty"`

	// TestContext Stand-in values for the hosting agent and session, used to resolve `agent.*` and `session.*` `$ref`s inside the tool configurations under test. Accepted by both `POST /v2/tools/test` and `POST /v2/tools/{tool_id}/test`.
	//
	// Example: {"agent":{"metadata":{"ticket_api_base":"https://tickets.example.com/api/v1/"},"secrets":{"ticket_api_token":"test-token"}},"session":{"metadata":{"tenant_corpus":"kb"}}}
	TestContext *TestLambdaToolContext `json:"test_context,omitempty"`

	// TestInput The input parameters to test the function with. The platform validates them against the discovered input schema.
	//
	// Example: {"order_count":10,"total_revenue":500}
	TestInput map[string]interface{} `json:"test_input"`

	// TimeoutSeconds Maximum execution time in seconds for this test. Overrides `execution_configuration` if specified. When omitted, the supplied `execution_configuration` timeout applies in full — up to 21600 seconds — and a request with none runs at 30 seconds. A budget longer than 300 seconds requires `stream_response` to be true; a non-streaming request with a larger budget is rejected.
	//
	// Example: 10
	TimeoutSeconds *int `json:"timeout_seconds,omitempty"`

	// ToolConfigurations Named configurations of other tools the code under test may invoke through its built-in `tool` module.
	// See the `tool_configurations` field on `CreateLambdaToolRequest` for semantics and constraints.
	ToolConfigurations *map[string]AgentToolConfiguration `json:"tool_configurations,omitempty"`
}

// TestLambdaToolRequestLanguage The programming language. Currently only 'python' (Python 3.12) is supported.
//
// Example: python
type TestLambdaToolRequestLanguage string

// TestLambdaToolResponse Response from testing a Lambda tool before creation. Contains validation, schema discovery, and execution results.
