// ToolInputEvent An event representing input to a tool call.
type ToolInputEvent struct {
	// ArgumentOverridePaths Dot-notation leaf paths supplied by the tool configuration's argument overrides rather than by the agent — for example `api_key`,
	// `config.auth.token`, or `items[0]`. These paths are frozen on the input event so that the agent's view of its own past tool calls stays
	// stable when the tool configuration changes: overrides are excluded from replayed calls regardless of how the override has evolved since.
	// Only the paths are frozen here; the resolved values at those paths are not — they are recomputed against the live session at each launch
	// and recorded on the corresponding `ToolOutputEvent.resolved_argument_overrides`.
	ArgumentOverridePaths *[]string `json:"argument_override_paths,omitempty"`

	// CreatedAt Timestamp when the event was created.
	//
	// Example: 2024-01-15T10:35:00Z
	CreatedAt time.Time `json:"created_at"`

	// Id The unique identifier for the event.
	//
	// Example: aev_user_001
	Id string `json:"id"`

	// SessionKey A unique key that identifies an agent session.
	//
	// Example: customer_support_chat
	SessionKey AgentSessionKey `json:"session_key"`

	// ToolCallId The identifier for the tool call.
	//
	// Example: call_tool_search_001
	ToolCallId string `json:"tool_call_id"`

	// ToolConfigurationName The name of the tool configuration being invoked, as defined in the agent's tool_configurations map.
	//
	// Example: customer_search
	ToolConfigurationName string `json:"tool_configuration_name"`

	// ToolInput Input data for the tool.
	//
	// Example: {"query":"weather in San Francisco"}
	ToolInput map[string]interface{} `json:"tool_input"`

	// ToolName Name of the tool being called.
	//
	// Example: web_search
	ToolName string `json:"tool_name"`

	// Type The type of event.
	Type string `json:"type"`
}

// ToolOutputEvent An event representing output from a tool call.
type ToolOutputEvent struct {
	// CreatedAt Timestamp when the event was created.
	//
	// Example: 2024-01-15T10:35:00Z
	CreatedAt time.Time `json:"created_at"`

	// Error Whether the tool call resulted in an error.
	Error bool `json:"error"`

	// Id The unique identifier for the event.
	//
	// Example: aev_user_001
	Id string `json:"id"`

	// OutputWrapped Whether `tool_output` is an envelope holding a non-object result: tools may return raw text, a number, or an
	// array, which is stored as `{"content": <result>}` so the event stays a JSON object. When true, the actual tool
	// result is the value under `content`; when false or absent, `tool_output` is the tool's own object result.
	OutputWrapped *bool `json:"output_wrapped,omitempty"`

	// ResolvedArgumentOverrides The values the tool configuration's argument overrides contributed to this call, keyed by the paths in
	// `ToolInputEvent.argument_override_paths`. `$ref` overrides are resolved against the session — agent secrets,
	// session metadata, and prior tool outputs — with secret values masked as `****`. Literal overrides appear as-is.
	//
	// Overlay these onto `ToolInputEvent.tool_input` at the matching paths to see exactly what the tool received.
	//
	// Absent when the tool short-circuits before running (for example, malformed arguments from the agent or an
	// unresolved dependency).
	//
	//
	// Example: {"api_key":"****","base_url":"https://api.example.com"}
	ResolvedArgumentOverrides *map[string]interface{} `json:"resolved_argument_overrides,omitempty"`

	// SessionKey A unique key that identifies an agent session.
	//
	// Example: customer_support_chat
	SessionKey AgentSessionKey `json:"session_key"`

	// ToolCallId The unique identifier for the tool call, matching the input event.
	//
	// Example: call_tool_search_001
	ToolCallId string `json:"tool_call_id"`

	// ToolConfigurationName The name of the tool configuration that was invoked, as defined in the agent's tool_configurations map.
	//
	// Example: customer_search
	ToolConfigurationName string `json:"tool_configuration_name"`

	// ToolName Name of the tool that was called.
	//
	// Example: web_search
	ToolName string `json:"tool_name"`

	// ToolOutput Output data from the tool.
	//
	// Example: {"result":"Current weather is 70°F and sunny"}
	ToolOutput map[string]interface{} `json:"tool_output"`

	// Type The type of event.
	Type string `json:"type"`
}

// ToolOutputOffloadingConfiguration Controls how large tool outputs are kept from overwhelming the agent context window.
// Tool outputs are inspected as they are produced. A small output is always passed through unchanged. A larger output is handled in one of two cases: when the output on its own is big enough to dominate the context, or when adding it to the conversation would leave too little room for the agent to continue. In either case the output is handled according to `mode` — stored as an artifact and replaced with a compact reference, or truncated in place with the head and tail preserved and the middle omitted. When stored as an artifact, the agent is expected to have artifact_read, artifact_grep, or artifact_jq configured so it can retrieve the full content on demand.
// All fields are optional; omitted fields fall back to defaults.
type ToolOutputOffloadingConfiguration struct {
	// ContextPercentage The fraction of the model's context window that a single tool output is allowed to occupy before it is considered large enough to offload on its own. The platform converts the fraction to a byte threshold using a bytes-per-token ratio for the model, then clamps it between `min_threshold_bytes` and `max_threshold_bytes`, so for very large context models this percentage is usually dominated by `max_threshold_bytes`, and for very small context models it is dominated by `min_threshold_bytes`.
	//
	// Example: 0.25
	ContextPercentage *float64 `json:"context_percentage,omitempty"`

	// Enabled Whether tool output offloading is active. Defaults to true. When disabled, tool outputs are always passed through to the agent verbatim.
	//
	// Example: true
	Enabled *bool `json:"enabled,omitempty"`

	// HeadroomPercentage The fraction of the model's context window at which offloading becomes sensitive to cumulative usage. When adding a tool output would push estimated total input tokens above this fraction of the context window, the output is offloaded even if it would otherwise be considered small enough to pass through. Token counts are estimated from output size using a bytes-per-token ratio for the model.
	// This is independent of the compaction `threshold_percent`: both can be configured on the same agent and both can apply. In practice it is often useful to set this below the compaction threshold so that large tool outputs are offloaded before compaction is triggered, avoiding the case where a large tool result is immediately summarized away. Setting this to 1.0 effectively disables the headroom behavior, leaving only the per-output size thresholds in effect.
	//
	// Example: 0.7
	HeadroomPercentage *float64 `json:"headroom_percentage,omitempty"`

	// MaxThresholdBytes An absolute ceiling on single-output size. Any output above this many bytes is considered large enough to offload on its own, regardless of the model's context window. This prevents unusually large outputs from slipping through on models with very large context windows.
	//
	// Example: 1048576
	MaxThresholdBytes *int64 `json:"max_threshold_bytes,omitempty"`

	// MinThresholdBytes A hard floor on offloading. Tool outputs below this size are always passed through to the agent unchanged, even when cumulative context usage is high. This ensures that short, useful outputs are never unnecessarily truncated or replaced with a reference.
	//
	// Example: 4096
	MinThresholdBytes *int64 `json:"min_threshold_bytes,omitempty"`

	// Mode How a large tool output is handled after it is selected for offloading.
	// In `artifact` mode, the full output is stored as a session artifact and replaced in the conversation with a compact reference containing the artifact id, size, shape, and hints for the available artifact tools. The agent can then use artifact_read, artifact_grep, or artifact_jq to retrieve just the parts it needs.
	// In `truncate` mode, the output is shortened in place to fit within the target size. The head and tail are preserved and the middle is replaced with a short notice explaining that content was omitted. No artifact is created.
	// When unset, the default is `artifact` if the agent has any of artifact_read, artifact_grep, or artifact_jq configured, and `truncate` otherwise.
	//
	// Example: artifact
	Mode *ToolOutputOffloadingConfigurationMode `json:"mode,omitempty"`
}

// ToolOutputOffloadingConfigurationMode How a large tool output is handled after it is selected for offloading.
// In `artifact` mode, the full output is stored as a session artifact and replaced in the conversation with a compact reference containing the artifact id, size, shape, and hints for the available artifact tools. The agent can then use artifact_read, artifact_grep, or artifact_jq to retrieve just the parts it needs.
// In `truncate` mode, the output is shortened in place to fit within the target size. The head and tail are preserved and the middle is replaced with a short notice explaining that content was omitted. No artifact is created.
// When unset, the default is `artifact` if the agent has any of artifact_read, artifact_grep, or artifact_jq configured, and `truncate` otherwise.
//
// Example: artifact
type ToolOutputOffloadingConfigurationMode string

