// TrustedTokenIssuer A customer identity provider whose signed tokens the platform accepts as end-user credentials.
// The registration is a trust anchor: the issuer URL and the JWKS the platform verifies signatures against.
// What a verified token grants is declared on the widget connector that references this registration by id.
type TrustedTokenIssuer struct {
	// CreatedAt Timestamp when the registration was created.
	//
	// Example: 2026-08-07T10:30:00Z
	CreatedAt time.Time `json:"created_at"`

	// Description A detailed description of what this trust registration is for.
	//
	// Example: Lets Acme portal users chat with the support agent.
	Description *string `json:"description,omitempty"`

	// Enabled Whether the registration currently accepts tokens. Disabling refuses every future sign-in immediately.
	//
	// Example: true
	Enabled bool `json:"enabled"`

	// Id The unique identifier of a trusted token issuer.
	//
	// Example: tki_9Kx2QpVn4mZr8YbLc5TdWe
	Id TrustedTokenIssuerId `json:"id"`

	// Issuer The issuer URL exactly as it appears in the `iss` claim of the identity provider's tokens. Immutable after creation.
	// A customer may register an issuer once; a duplicate registration returns `409`.
	//
	//
	// Example: https://acme.okta.com/oauth2/default
	Issuer string `json:"issuer"`

	// JwksFetchError The most recent JWKS fetch error, absent while fetching is healthy.
	//
	// Example: jwks fetch failed: connection timed out
	JwksFetchError *string `json:"jwks_fetch_error,omitempty"`

	// JwksKeyCount The number of signing keys in the most recent successful JWKS fetch.
	//
	// Example: 2
	JwksKeyCount *int32 `json:"jwks_key_count,omitempty"`

	// JwksUri The HTTPS URL of the issuer's JSON Web Key Set.
	// The platform fetches it server-side and refreshes it periodically, so new signing keys become effective on the next refresh.
	// A token signed with a key the platform has not yet seen triggers one immediate refresh.
	// When a refresh fails, previously fetched keys remain in use until a refresh succeeds.
	//
	//
	// Example: https://acme.okta.com/oauth2/default/v1/keys
	JwksUri string `json:"jwks_uri"`

	// LastJwksFetchAt Timestamp of the most recent successful fetch of the issuer's JWKS. Absent until the first successful fetch.
	//
	// Example: 2026-08-12T10:30:00Z
	LastJwksFetchAt *time.Time `json:"last_jwks_fetch_at,omitempty"`

	// Name The human-readable name of the trusted issuer.
	//
	// Example: Acme Okta production
	Name string `json:"name"`

	// UpdatedAt Timestamp when the registration was last updated.
	//
	// Example: 2026-08-07T14:45:00Z
	UpdatedAt *time.Time `json:"updated_at,omitempty"`
}

// TrustedTokenIssuerId The unique identifier of a trusted token issuer.
//
// Example: tki_9Kx2QpVn4mZr8YbLc5TdWe
type TrustedTokenIssuerId = string

