// UpdateInitialInstructionRequest Request object for updating an existing initial instruction.
type UpdateInitialInstructionRequest struct {
	// Description A detailed description of what this instruction does.
	//
	// Example: Enhanced initial context and guidelines for customer support interactions
	Description *string `json:"description,omitempty"`

	// Enabled Whether the instruction is enabled.
	//
	// Example: true
	Enabled *bool `json:"enabled,omitempty"`

	// Metadata Arbitrary metadata associated with the instruction.
	//
	// Example: {"author":"support-team","last_reviewed":"2024-01-15","version":"1.1.0"}
	Metadata *map[string]interface{} `json:"metadata,omitempty"`

	// Name The human-readable name of an instruction.
	//
	// Example: Customer Support Initial Instruction
	Name *InstructionName `json:"name,omitempty"`

	// Template The instruction template content. How it is rendered depends on the sibling `template_type`.
	//
	// When `template_type` is `text`, the content is used verbatim as the instruction and no variables are substituted.
	//
	// When `template_type` is `velocity`, the content is rendered with the Velocity engine and the following variables are available:
	// - `$agent.name` - Agent name
	// - `$agent.key` - Agent key
	// - `$agent.metadata` - Agent metadata map
	// - `$session.key` - Session key
	// - `$session.metadata` - Session metadata map (includes user-provided context from test/runtime)
	// - `$currentDate` - Current date/time in ISO 8601 format (e.g., "2025-10-24T15:30:45Z")
	// - `$tools` - List of tool maps, each with `name` and `description` fields
	//
	// Example: `You are a helpful customer support agent. Agent: $agent.name. Today is $currentDate. Available tools: #foreach($tool in $tools)${tool.name}#if($foreach.hasNext), #end#end`
	//
	//
	// Example: You are an expert customer support agent for $agent.name. Available tools: #foreach($tool in $tools)${tool.name}#if($foreach.hasNext), #end#end
	Template *InstructionTemplate `json:"template,omitempty"`

	// TemplateType The templating engine used to render the instruction's template.
	//
	// - `velocity`: render the template with the Velocity engine, substituting agent, session, and tool variables.
	// - `text`: use the template verbatim as plain text, with no variable substitution.
	//
	//
	// Example: velocity
	TemplateType *TemplateType `json:"template_type,omitempty"`

	// Type The type of instruction to update.
	//
	// Example: initial
	Type string `json:"type"`
}

